import{_ as s,l as i,o as e,c as d,v as r,p as l,x as t,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"gshare 预测器","description":"","frontmatter":{"title":"gshare 预测器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gshare-predictor.md","filePath":"cs/gshare-predictor.md","lastUpdated":1789023840000}'),p={name:"cs/gshare-predictor.md"};function E(P,a,_,m,B,g){const o=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="gshare-预测器" tabindex="-1">gshare 预测器 <a class="header-anchor" href="#gshare-预测器" aria-label="Permalink to &quot;gshare 预测器&quot;">​</a></h1><div class="epigraph"><p>把全局历史与分支地址异或后再去索引模式表，别名少、硬件也省；锦标赛只是再加一路局部预测来仲裁。</p><footer>—— 据 McFarling, Combining Branch Predictors, DEC WRL TN-36, 1993 整理</footer></div><p><a href="/cs/isa-abi-boundary">上一课</a>把数字系统收到 ISA/ABI 合同：寄存器、调用约定、端序与对齐已经固定。<a href="/cs/control-hazard-predict">组成主干</a>已经用一位饱和计数器猜方向，<a href="/cs/btb-ras">BTB 与返回栈</a>已经把目标从 ALU 里抢出来。本课不重讲冲刷，也不从比特或证明助手再起。缺口是：相关分支——「前一次比较的结果改写这一次该不该跳」——一位表按 PC 索引看不见这条相关。微结构进阶从这里开始：先交出 gshare。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环结尾的 <code>bne</code> 几乎总成功，出循环那一次失败：两位饱和计数器要错两次才改过来。更糟的是 <code>if (a) … if (a &amp;&amp; b)</code>：第二条的方向与第一条相关，按 PC 分槽的 PHT 把两次当成独立硬币。Yeh 与 Patt 的两级自适应（全局/局部历史寄存器去索引第二级表）已经点名这件事；直接用长历史当索引，表项爆炸，且不同 PC 挤在同一行。缺口不是再加一位计数器，而是<strong>用少量全局历史，按地址散列进一张两位表</strong>。</p><p><span class="marginnote">McFarling 把「全局历史」方案叫 GAs 一类；gshare 是把 PC 与 GHR 异或。他同时提出 bimodal 与 gshare 的锦标赛（tournament）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护一条移位寄存器 GHR：每条退休（或至少核对过的）条件分支把 0/1 推进来。预测时取 <code>index = PC ⊕ GHR</code>（截到表宽），读两位饱和计数器：≥2 猜成功。核对后按普通饱和规则 ±1，并移位 GHR。</p>',8)),(e(),l(h,null,{default:t(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%88%86%E6%94%AF%20PC%22%5D%20--%3E%20XOR%5B%22PC%20%E5%BC%82%E6%88%96%20GHR%22%5D%0A%20%20GHR%5B%22%E5%85%A8%E5%B1%80%E5%8E%86%E5%8F%B2%22%5D%20--%3E%20XOR%0A%20%20XOR%20--%3E%20PHT%5B%22%E4%B8%A4%E4%BD%8D%20PHT%22%5D%0A%20%20PHT%20--%3E%20DIR%5B%22%E9%A2%84%E6%B5%8B%E6%96%B9%E5%90%91%22%5D%0A%20%20DIR%20--%3E%20CHK%5B%22EX%20%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E8%AE%A1%E6%95%B0%E5%99%A8%E4%B8%8E%20GHR%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与纯 GHR 索引比，异或让同一段历史在不同 PC 上散开，减轻别名。与纯 PC 索引比，同一 PC 在不同历史上走不同槽，相关被记住。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>误预测率进 CPI：<a href="/cs/control-hazard-predict">控制冒险</a> 的公式仍是频率 × 误预测 × 损失拍。乱序核损失拍数比五级大一个数量级，所以表要准。gshare 的历史长度是交易：太短看不见相关，太长则训练慢、别名多。锦标赛再加一张局部（每 PC 一段历史）和选择器：两种预测器各对一类分支，选择器本身也是饱和计数器。</p><p>gshare 状态不是 ISA。上下文切换不必保存；冷表只让误预测暂时升高。推测执行会用推测中的分支去更新 GHR，错了要恢复——那是后课恢复检查点，本课只要求「有一份架构 GHR 在核对后提交」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TAGE 的几何长度与部分标签，不引入感知器的权重和。间接跳转仍走上一课的 BTB；gshare 只管条件方向。也不把预测器写成可被用户读写的 CSR。</p><p>后课默认：谈到相关预测，先想到 PC 与 GHR 的异或索引；损失拍仍按核对点到 IF 的深度计。更长、可变的历史是下一课 TAGE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>相关分支要用全局历史，不能只按 PC 查一位表。</li><li>gshare 用 <code>PC ⊕ GHR</code> 索引两位 PHT，是 McFarling 对两级表的实用化。</li><li>几何历史与标签匹配是下一课的缺口。</li><li>出处：McFarling, <em>WRL TN-36</em>, 1993；Yeh and Patt, 两级自适应预测。</li></ul>',9))])}const T=s(p,[["render",E]]);export{C as __pageData,T as default};
